import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"FaultDeck MVP Plan (P0)","description":"","frontmatter":{},"headers":[],"relativePath":"design/mvp-plan.md","filePath":"design/mvp-plan.md"}`),a={name:`design/mvp-plan.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="faultdeck-mvp-plan-p0" tabindex="-1">FaultDeck MVP Plan (P0) <a class="header-anchor" href="#faultdeck-mvp-plan-p0" aria-label="Permalink to “FaultDeck MVP Plan (P0)”">​</a></h1><p>Date: 2026-11-02 · Source: ChatGPT architecture review (archive in docs/review/) + user decision 中文版:<a href="/faultdeck/zh/design/mvp-plan.html">中文文档</a></p><h2 id="p0-scope-minimal-viable-tcp-fault-experiments" tabindex="-1">P0 Scope: minimal viable TCP fault experiments <a class="header-anchor" href="#p0-scope-minimal-viable-tcp-fault-experiments" aria-label="Permalink to “P0 Scope: minimal viable TCP fault experiments”">​</a></h2><ul><li>Rust CLI (<code>faultdeck</code>)</li><li>Toxiproxy adapter (TCP proxy fault injection)</li><li>Experiment YAML DSL (scenario orchestration: steps / duration / targets)</li><li>Fault types: latency, cut connection, blackhole (timeout), bandwidth throttle</li><li>Automatic recovery (Lifecycle + Rollback, Safety Guard watchdog: faults must be undone even if the process is killed)</li><li>JSON experiment report (timeline, injection parameters, recovery verification result)</li></ul><h2 id="hard-acceptance-gates" tabindex="-1">Hard acceptance gates <a class="header-anchor" href="#hard-acceptance-gates" aria-label="Permalink to “Hard acceptance gates”">​</a></h2><ol><li><code>faultdeck run examples/tcp-reconnect.yaml</code> runs fully automated, no GUI</li><li><strong>After Ctrl-C / kill -9, 100% of faults are rolled back</strong> (watchdog fallback) and target connections return to normal</li><li>Reports are reproducible: re-running the same YAML yields consistent results</li><li>Safety Guard refuses experiments targeting management networks (NICs/subnets carrying SSH/ZeroTier)</li></ol><h2 id="crate-layout" tabindex="-1">Crate layout <a class="header-anchor" href="#crate-layout" aria-label="Permalink to “Crate layout”">​</a></h2><table tabindex="0"><thead><tr><th>crate</th><th>responsibility</th></tr></thead><tbody><tr><td>faultdeck-core</td><td>fault types, targets, state model</td></tr><tr><td>faultdeck-scenario</td><td>experiment YAML DSL parsing &amp; scheduling</td></tr><tr><td>faultdeck-backend</td><td>backend trait (semantic declaration + capability query)</td></tr><tr><td>faultdeck-toxiproxy</td><td>Toxiproxy REST API adapter</td></tr><tr><td>faultdeck-safety</td><td>watchdog, lease, forced rollback</td></tr><tr><td>faultdeck-report</td><td>metrics collection &amp; JSON report</td></tr><tr><td>faultdeck-cli</td><td>command-line entry</td></tr></tbody></table><h2 id="milestones" tabindex="-1">Milestones <a class="header-anchor" href="#milestones" aria-label="Permalink to “Milestones”">​</a></h2><ul class="task-list-container"><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-0" disabled="disabled"><label class="task-list-item-label" for="task-item-0"> FD-P0-1 repo skeleton: cargo workspace + 7 crates + CI (rustfmt/clippy/test)</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-1" disabled="disabled"><label class="task-list-item-label" for="task-item-1"> FD-P0-2 core type model + scenario YAML parsing (serde, with validation errors)</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-2" disabled="disabled"><label class="task-list-item-label" for="task-item-2"> FD-P0-3 toxiproxy adapter (hosted toxiproxy-server, proxy &amp; fault CRUD)</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-3" disabled="disabled"><label class="task-list-item-label" for="task-item-3"> FD-P0-4 safety: watchdog process + lease + forced rollback (incl. orphaned-child scenario)</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-4" disabled="disabled"><label class="task-list-item-label" for="task-item-4"> FD-P0-5 CLI run/report subcommands + JSON report</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-5" disabled="disabled"><label class="task-list-item-label" for="task-item-5"> FD-P0-6 three example scenarios + integration/recovery tests + README quick start</label></li></ul><h2 id="p1-preview" tabindex="-1">P1 preview <a class="header-anchor" href="#p1-preview" aria-label="Permalink to “P1 preview”">​</a></h2><p>tc/netem adapter (netlink directly, not shelling out to tc), TCP/UDP, traffic selection, burst loss, reordering, netns isolation; test environments use dedicated netns to keep the host clean.</p>`,12)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};